import sailpoint.object.*;

  import org.apache.log4j.Logger;

  Logger log = Logger.getLogger("iiq.alpha.Alpha-Rule-ActiveDirectory ProvisionPolicy DN Calculation Rule");
  log.debug("Alpha-Rule-ActiveDirectory DN Calculation Rule - STARTS");

boolean createPrivilegeAccount = false;
//Get createPrivilegeAccount property set in Account Selector Rule for privilege account creation

if(null != context.getProperty("createPrivilegeAccount"))
{
  createPrivilegeAccount = Boolean.parseBoolean(context.getProperty("createPrivilegeAccount"));
  log.debug("createPrivilegeAccount"+createPrivilegeAccount );
}


//Check if createPrivilegeAccount  is true, then create in privileged users OU

if(createPrivilegeAccount )
{
String distinguishedName = "CN=" + sAMAccountName + ",OU=Privileged Users,OU=Users,OU=Alpha,DC=tcs,DC=sailpointiamcoe,DC=com";
 log.debug("distinguishedName : "+distinguishedName);
 log.debug("Alpha-Rule-ActiveDirectory DN Calculation Rule - ENDS");
return distinguishedName;
}

  //Logic to calculate DN. Set OU path based in employeeType, and referring Alpha-Custom-Joiner OU Mappings Custom Object to set OU based on Department and Location 

  String employeeType = identity.getAttribute("userType");
  String userDept = identity.getAttribute("department");
  String userLocation = identity.getAttribute("city");
  String departmentOU = "";
  String locationOU = "";
  String typeOU = "";
  String baseOU = "";

  //TODO: what if the usertype is not correct ot null. Shall we create a temp OU to place the users???
  if(null!=employeeType)
  {
    if("Employee".equalsIgnoreCase(employeeType))
      typeOU = "Permanent Employees";
    else if("Contractor".equalsIgnoreCase(employeeType))
      typeOU = "Contractors";
  }
  // call custom object to get the Department and Location OU based in Users dept and location
  Custom customObj = context.getObject(Custom.class,"Alpha-Custom-Joiner OU Mappings");

  if(null!=customObj)
  {
    baseOU = customObj.get("baseOU");

    Map deptMap = customObj.get("Department");
    if(null != deptMap)
    {
      if(null != deptMap.get(userDept))
        departmentOU = deptMap.get(userDept);
    }

    Map locationMap = customObj.get("Location");
    if(null != locationMap)
    {
      if(null != locationMap.get(userLocation))
        locationOU = locationMap.get(userLocation);
    }

  }

  String distinguishedName = "CN=" + sAMAccountName + ",OU=" + departmentOU + ",OU=" + locationOU + ",OU=" + typeOU + ",OU=Users,OU=" + baseOU+ ",DC=tcs,DC=sailpointiamcoe,DC=com";

  log.debug("distinguishedName is :"+distinguishedName);
 log.debug("Alpha-Rule-ActiveDirectory DN Calculation Rule - ENDS");
  return distinguishedName;
